std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        boost::counting_iterator<std::size_t>(0),
        boost::counting_iterator<std::size_t>(cols_),
        result.begin(),
        [this](std::size_t c) {
            return std::accumulate(
                boost::counting_iterator<std::size_t>(0),
                boost::counting_iterator<std::size_t>(rows_),
                0.0,
                [this, c](double s, std::size_t r) { return s + at(r, c); });
        });
    return result;
}

